// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    MockERC20 token;
    SignatureBouncer maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new MockERC20();
        maker = new SignatureBouncer();
        vm.warp(1_000_000);
    }

    function testFuzz_property(
        bool isLong,
        bool isCall,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce
    ) public {
        // long orders are the case that distinguishes reference from mutant
        vm.assume(isLong);
        duration = bound(duration, 1, 10_000 days - 1);
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);

        c.fillOrder(order, hex"", floorAssetTokenIds);

        // RULE: for every filled long order, the expiration is keyed by the
        // long position id uint256(orderHash) and equals fill time + duration.
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + duration,
            "long position expiration must be keyed by the long position id"
        );
    }
}

// Adversarial counterparty: an order maker that accepts every EIP-1271
// signature, so fillOrder can be driven for arbitrary fuzzed orders.
contract SignatureBouncer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

// Minimal token standing in for the base asset: every transfer succeeds.
contract MockERC20 {
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
